'use strict';
(() => {
const $ = id => document.getElementById(id);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = (n,d=0) => new Intl.NumberFormat('en-US',{maximumFractionDigits:d}).format(Number(n)||0);
const money = n => `₸ ${fmt(n)}`;
const dateLabel = d => d ? new Date(d).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Almaty'}) : '—';
const stamp = d => d ? new Date(d).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Almaty'}) : '—';
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const PREVIEW = window.STUDIO_PREVIEW || null;
const Final = window.StockroomFinal; if(!Final) throw new Error("Missing /studio/final-integration.js");
let previewRole = 'owner';
const state = {user:null,config:{},products:[],analytics:null,movements:[],videos:[],route:'inventory',days:30,lead:7,review:14,buffer:3,analyticsCategory:'',query:'',category:'',status:'',sort:'sku',page:1,view:'table',historyReason:'',mediaStatus:'',productId:null,tab:'details',sequence:0,auto:false};
const paths={
 overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
 inventory:'M3 7l9-4 9 4v10l-9 4-9-4zM3 7l9 4 9-4M12 11v10',
 analytics:'M4 20V11M10 20V4M16 20V8M22 20H2',
 restock:'M4 8h13l-3-3M20 16H7l3 3M17 8a7 7 0 0 1 3 5M7 16a7 7 0 0 1-3-5',
 activity:'M3 12h4l3-7 4 14 3-7h4',
 media:'M4 5h16v14H4zM10 9l5 3-5 3z',
 barcode:'M4 6h1v12H4zM7 5h2v14H7zM11 5h1v14h-1zM14 5h3v14h-3zM19 6h1v12h-1z',
 settings:'M5 6h14M5 12h14M5 18h14M8 3v6M16 9v6M10 15v6',
 arrow:'M4 12h15M14 6l6 6-6 6',
 alert:'M12 3L2 21h20zM12 9v5M12 17h.01',
 plus:'M12 4v16M4 12h16',
 clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
 bag:'M5 7h14l1 14H4zM8 7V5a4 4 0 0 1 8 0v2'
};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.inventory}"/></svg>`;}
const isStaff=()=>['owner','employee'].includes(state.user?.role), isAdmin=()=>state.user?.role==='owner';
const roleName = role => ({owner:'Administrator',employee:'Seller',customer:'Buyer'}[role]||'Guest');
function notice(text,error=false){$('notice').textContent=text;$('notice').className=error?'error':'';$('notice').hidden=!text;}
async function previewApi(url,opts={}){
 const endpoint=url.split('?')[0]; const copy=x=>JSON.parse(JSON.stringify(x));
 if(endpoint==='/api/config')return {demo:true,demo_password:'Demo1234!',max_video_bytes:41943040,demo_accounts:[{role:'Administrator',email:'owner@shop.example'},{role:'Seller',email:'employee1@shop.example'},{role:'Buyer',email:'customer@shop.example'}]};
 if(endpoint==='/api/login'){const b=JSON.parse(opts.body);previewRole=b.email.startsWith('owner')?'owner':b.email.startsWith('employee')?'employee':'customer';return {user_id:1,email:b.email,role:previewRole,role_label:roleName(previewRole)};}
 if(endpoint==='/api/logout'){previewRole=null;return {ok:true};}
 if(endpoint==='/api/me'){if(!previewRole)throw Object.assign(new Error('Please sign in.'),{status:401});return {user_id:1,email:previewRole==='owner'?'owner@shop.example':previewRole==='employee'?'employee1@shop.example':'customer@shop.example',role:previewRole,role_label:roleName(previewRole)};}
 if(opts.method && opts.method!=='GET')throw new Error('Design preview only. No database changes are saved. Install the update to use your live data.');
 if(endpoint==='/api/products')return copy(PREVIEW.products);
 if(endpoint==='/api/studio/analytics'){
  const q=new URLSearchParams(url.split('?')[1]),days=Number(q.get('days'))||30;
  const source=PREVIEW.windows?.[days];
  if(source&&window.STUDIO_PREVIEW_ENGINE){
    const opt={days,lead_days:Number(q.get('lead')??7),review_days:Number(q.get('review')??14),buffer_days:Number(q.get('buffer')??3),category:q.get('category')||''};
    const result=window.STUDIO_PREVIEW_ENGINE.derive(source.rows,source.trend,source.meta,opt);
    if(opt.category){
      const distribute=(total)=>{const w=result.trend.map((r,i)=>2+(i*7%11)),sum=w.reduce((a,b)=>a+b,0);let left=total;return w.map((v,i)=>{const n=i===w.length-1?left:Math.floor(total*v/sum);left-=n;return n;});};
      const current=distribute(result.summary.units_sold),prior=distribute(result.summary.previous_units_sold);
      result.trend=result.trend.map((r,i)=>({...r,units:current[i],previous_units:prior[i]}));
    }
    return result;
  }
  return copy(PREVIEW.analytics);
 }
 if(endpoint==='/api/studio/movements')return {rows:copy(PREVIEW.movements),limit:100};
 if(endpoint==='/api/studio/videos')return {rows:copy(PREVIEW.videos||[]),limit:100};
 if(/\/videos$/.test(endpoint))return [];
 if(/\/movements$/.test(endpoint))return copy(PREVIEW.movements.filter(x=>x.product_id===Number(endpoint.split('/')[3])));
 return {};
}
async function api(url,opts={}){
 if(PREVIEW)return previewApi(url,opts);
 const controller=new AbortController(), timeout=setTimeout(()=>controller.abort(),opts.timeout||15000);
 const headers={...(opts.body && !(opts.body instanceof Blob)?{'Content-Type':'application/json'}:{}),...opts.headers};
 try{
  const response=await fetch(url,{credentials:'same-origin',...opts,headers,signal:controller.signal});
  const data=await response.json().catch(()=>({}));
  if(!response.ok)throw Object.assign(new Error(data.error||`Request failed (${response.status}).`),{status:response.status});
  return data;
 }catch(e){if(e.name==='AbortError')throw new Error(opts.method && opts.method!=='GET'?'The result could not be confirmed. Check the current record before submitting again.':'The server took too long to respond. Refresh to try again.');throw e;}finally{clearTimeout(timeout);}
}
function params(){return new URLSearchParams({days:state.days,lead:state.lead,review:state.review,buffer:state.buffer,category:state.analyticsCategory}).toString();}
function picture(p){if(PREVIEW?.images?.[slug(p.category)])return PREVIEW.images[slug(p.category)];return `/img/optimised/${slug(p.category)}.webp`;}
function images(){document.querySelectorAll('img[data-photo]').forEach(im=>{im.onerror=()=>{im.onerror=null;im.src='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80"><rect width="80" height="80" fill="#e5e7ce"/><path d="M20 29l20-9 20 9v22l-20 9-20-9zM20 29l20 9 20-9M40 38v22" fill="none" stroke="#657151" stroke-width="2"/></svg>');};});}
function badge(status){const labels={healthy:'In stock',low:'Low stock',out:'Out of stock',critical:'Urgent',high:'Reorder',watch:'Watch',pending:'In review',published:'Published',rejected:'Rejected',archived:'Archived',uploading:'Uploading'};return `<span class="badge ${esc(status)}">${status==='low'||status==='critical'||status==='out'?'! ':''}${labels[status]||esc(status)}</span>`;}
function productStatus(p){return Number(p.quantity)===0?'out':Number(p.quantity)<=Number(p.reorder_threshold)?'low':'healthy';}
function productCell(p){return `<div class="product-cell"><img data-photo class="thumb" loading="lazy" src="${picture(p)}" alt=""><div><strong>${esc(p.name)}</strong><span class="sku">${esc(p.sku)}</span></div></div>`;}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function range(){return `<div class="range" role="group" aria-label="Analysis period">${[7,30,90].map(d=>`<button data-days="${d}" aria-pressed="${state.days===d}" class="${state.days===d?'active':''}">${d} days</button>`).join('')}</div>`;}
function kpi(label,value,hint,name='inventory',emphasis=false){return `<article class="kpi ${emphasis?'emphasis':''}"><div class="label">${label}${icon(name)}</div><div class="value">${value}</div><div class="hint">${hint}</div></article>`;}
function nav(){
 const items=isAdmin()?[['overview','Overview'],['inventory','Inventory'],['analytics','Analytics'],['restock','Replenishment'],['activity','Activity'],['media','Product videos']]:isStaff()?[['overview','Overview'],['inventory','Inventory'],['activity','Activity'],['media','Product videos']]:[['inventory','Catalogue'],['media','Product videos']];
 if(isStaff())items.push(['barcode','Barcode simulator']);
 items.push(['settings','Help & settings']);
 $('nav').innerHTML=items.map(([id,title])=>`<a class="nav-link ${state.route===id?'active':''}" href="#${id}" ${state.route===id?'aria-current="page"':''}>${icon(id)}<span>${title}</span>${id==='restock'&&state.analytics?.summary.needs_attention?`<span class="count">${state.analytics.summary.needs_attention}</span>`:''}</a>`).join('');
 // Barcode and historical reports are part of this workspace.
 $('accountName').textContent=roleName(state.user?.role);$('accountRole').textContent=state.user?'Signed-in workspace':'Browse the catalogue';$('avatar').textContent=roleName(state.user?.role)[0];
 $('signInButton').hidden=!!state.user;$('logoutButton').hidden=!state.user;
 $('crumbPage').textContent=(items.find(([r])=>r===state.route)?.[1]||'Inventory').toUpperCase();
}
function allowed(route){return ['inventory','media','settings'].includes(route)||(isStaff()&&['overview','activity','barcode'].includes(route))||(isAdmin()&&['analytics','restock'].includes(route));}
function closeMenu(){$('sidebar').classList.remove('open');$('shade').hidden=true;$('menuButton').setAttribute('aria-expanded','false');}
function metaLine(d){return `<div class="metrics-note"><span class="tag">${PREVIEW?'PREVIEW DATA':esc(d.meta.database_name)}</span><span class="tag">${esc(d.options.category||'All categories')}</span>${d.options.category?'<button class="text-button" data-clear-scope>Clear category</button>':''}<span>${dateLabel(d.meta.window_start)} – ${dateLabel(new Date(new Date(d.meta.window_end_exclusive).getTime()-86400000))} · complete days · Almaty time</span><span>Current stock at ${stamp(d.meta.captured_at)}</span></div>`;}
function methods(d){return `<details class="methods"><summary>How these insights are calculated</summary><p><strong>Sales:</strong> only negative movements marked <code>sale</code>. Deliveries and corrections are excluded. Days without recorded sales stay in the denominator.</p><p><strong>Rate = recorded units sold ÷ ${d.options.days} complete days.</strong> Days of cover = current quantity ÷ that rate. Estimates need at least 5 sale records on 3 different dates and movement history reaching the start of the window. These are minimum safeguards, not proof of a reliable demand model.</p><p><strong>Replenishment review:</strong> target stock is the greater of threshold + 1 and rate × (lead time + review cycle + buffer). Subtract current stock, round up, and never go below zero. For limited evidence, use threshold + 1 only. Suggestions do not place orders or change stock.</p><p>Availability history, product age, orders already in transit and supplier pack sizes are not recorded. A zero means <em>no recorded sales</em>, not proven lack of demand. Valuation uses current list prices; it is not revenue, margin or a formal inventory-turnover ratio.</p><p>History starts: ${stamp(d.meta.history_start)}. Latest movement: ${stamp(d.meta.history_end)}. Source: ${esc(d.meta.database_name)}. ${d.summary.estimates_available} product(s) pass the minimum scenario safeguards.</p></details>`;}
function trendChart(d){
 const a=d.trend,w=620,h=212,left=33,right=12,top=20,bottom=33,max=Math.max(3,...a.map(p=>Math.max(p.units,p.previous_units))), x=i=>left+i*(w-left-right)/Math.max(1,a.length-1),y=n=>h-bottom-n/max*(h-top-bottom);
 if(!a.length)return '<div class="empty">No recorded series is available.</div>';
 const line=key=>a.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p[key]).toFixed(1)}`).join(' ');
 const ticks=[0,1,2,3].map(t=>{const n=max*t/3;return `<line class="gridline" x1="${left}" y1="${y(n)}" x2="${w-right}" y2="${y(n)}"/><text x="${left-9}" y="${y(n)+4}" text-anchor="end">${fmt(n)}</text>`;}).join('');
 const indices=[...new Set([0,Math.floor((a.length-1)/3),Math.floor((a.length-1)*2/3),a.length-1])];
 return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Recorded sales per day. ${d.summary.units_sold} units in the selected period; ${d.summary.previous_units_sold} in the previous equal period."><title>Daily recorded sales in units</title>${ticks}<path class="area" d="${line('units')} L${x(a.length-1)},${h-bottom} L${left},${h-bottom}Z"/><path class="previous" d="${line('previous_units')}"/><path class="line" d="${line('units')}"/>${indices.map(i=>`<text x="${x(i)}" y="${h-10}" text-anchor="${i===0?'start':i===a.length-1?'end':'middle'}">${dateLabel(a[i].date)}</text>`).join('')}</svg></div>`;
}
function trendPanel(d){return `<section class="panel"><div class="panel-head"><div><h3>Sales, over time</h3><p>Recorded units sold per day</p><div class="legend"><span><i></i>Selected period</span><span class="prior"><i></i>Previous ${state.days} days</span></div></div><span class="tag">UNITS</span></div>${trendChart(d)}<details class="chart-data"><summary>View daily values</summary><div class="table-wrap"><table><caption class="sr-only">Daily recorded sales and corresponding day in the previous period</caption><thead><tr><th scope="col">Date</th><th scope="col">Units</th><th scope="col">Previous period</th></tr></thead><tbody>${d.trend.map(r=>`<tr><td>${esc(r.date)}</td><td>${fmt(r.units)}</td><td>${fmt(r.previous_units)}</td></tr>`).join('')}</tbody></table></div></details></section>`;}
function barsPanel(d){const max=Math.max(1,...d.fastest.map(p=>p.sold_units));return `<section class="panel"><div class="panel-head"><div><h3>Fastest-selling products</h3><p>Ranked by recorded units, not deliveries</p></div></div><div class="bars">${d.fastest.length?d.fastest.slice(0,5).map(p=>`<div class="bar-row"><div class="bar-meta"><button class="text-button" data-open="${p.product_id}">${esc(p.sku)} · ${esc(p.name)}</button><strong>${fmt(p.sold_units)}</strong></div><div class="bar-track"><div class="bar-fill" data-width="${p.sold_units/max*100}"></div></div></div>`).join(''):'<div class="empty"><p>No sales recorded in this window. This chart never counts deliveries as sales.</p></div>'}</div></section>`;}
function widths(){document.querySelectorAll('[data-width]').forEach(el=>{el.style.width=Number(el.dataset.width)+'%';});}
function statusPanel(d){const s=d.summary.status,total=Math.max(1,d.summary.products);return `<section class="panel"><div class="panel-head"><div><h3>Stock health</h3><p>Current product lines, not individual units</p></div></div><div class="panel-body"><div class="stacked" role="img" aria-label="${s.healthy} in stock, ${s.low} low stock, ${s.out} out of stock">${['healthy','low','out'].map(k=>`<div class="${k}" data-width="${s[k]/total*100}"></div>`).join('')}</div>${[['healthy','In stock','Above reorder threshold'],['low','Low stock','At or below threshold'],['out','Out of stock','Zero available units']].map(([k,name,note])=>`<div class="mini-line"><span class="swatch ${k}"></span><div>${name}<p>${note}</p></div><span class="number">${fmt(s[k])}</span></div>`).join('')}</div></section>`;}
function queueTable(rows,short=false){return `<div class="table-wrap responsive-table"><table><caption class="sr-only">Products to review for replenishment</caption><thead><tr><th scope="col">Product</th><th scope="col">Priority</th><th scope="col" class="numeric">On hand</th><th scope="col">Cover estimate</th>${short?'':'<th scope="col" class="numeric">Review quantity</th>'}<th scope="col"><span class="sr-only">Action</span></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${productCell(p)}</td><td data-label="Priority">${badge(p.priority)}<span class="cell-note">${esc(p.reason)}</span></td><td data-label="On hand" class="numeric">${fmt(p.quantity)}</td><td data-label="Cover estimate">${p.days_of_cover===null?'<span class="muted">Not estimated</span>':`${fmt(p.days_of_cover,1)} days`}<span class="cell-note">${p.days_of_cover===null?'Limited sales evidence':'At the same recorded sales rate'}</span></td>${short?'':`<td data-label="Review quantity" class="numeric">${fmt(p.review_quantity)}<span class="cell-note">${esc(p.quantity_basis)}</span></td>`}<td><button class="button small secondary" data-open="${p.product_id}">Review →</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No replenishment flags in the selected scope.</div></td></tr>'}</tbody></table></div>`;}
function overview(){
 if(!isAdmin())return staffOverview();
 const d=state.analytics,s=d.summary;
 return heading('A WORKSPACE THAT WORKS','Inventory overview','The essentials first. Details when you need them.',range())+metaLine(d)+`<div class="kpis">${kpi('Units sold',fmt(s.units_sold),s.sales_change_percent===null?'No previous-period baseline':`${s.sales_change_percent>0?'+':''}${fmt(s.sales_change_percent,1)}% vs previous ${state.days} days`,'bag')}${kpi('Needs attention',fmt(s.needs_attention),'Products to review for replenishment','alert',true)}${kpi('No recorded sales',fmt(s.no_recorded_sales_count),`With stock · last ${state.days} days`,'clock')}${kpi('Stock at list price',money(s.listed_stock_value),'Current price × current quantity','inventory')}</div><section class="attention-banner"><div class="intro"><span class="attention-icon">${icon('restock')}</span><div><h3>${s.needs_attention?`${s.needs_attention} products need a closer look.`:'Your reorder queue is clear.'}</h3><p>${s.needs_attention?'Check low stock and estimated coverage before your next order.':'Keep recording sales to improve replenishment decisions.'}</p></div></div><a href="#restock" class="button">Review replenishment ${icon('arrow')}</a></section><div class="grid-two">${trendPanel(d)}${statusPanel(d)}</div><div class="subhead"><h2>What needs attention</h2><a class="text-button" href="#restock">View full list →</a></div><section class="panel">${queueTable(d.queue.slice(0,4),true)}</section><p class="toolbar-note">Estimates use recorded sales only. No automatic orders or stock changes.</p>`;
}
function staffOverview(){const low=state.products.filter(p=>productStatus(p)!=='healthy');return heading('STORE OPERATIONS','Your store, in order.','Find a product, record a movement, and keep stock up to date.',`<a class="button" href="#inventory">Open inventory ${icon('arrow')}</a>`)+`<div class="kpis">${kpi('Product lines',fmt(state.products.length),'Available in the catalogue')}${kpi('Low / out of stock',fmt(low.length),'Check current availability','alert',true)}${kpi('Units on hand',fmt(state.products.reduce((a,p)=>a+Number(p.quantity),0)),'Current stock across all items')}${kpi('Published videos',fmt(state.products.reduce((a,p)=>a+Number(p.video_count),0)),'Product-linked demonstrations','media')}</div><div class="subhead"><h2>Low-stock products</h2><a href="#inventory" class="text-button">Browse all →</a></div><section class="panel">${inventoryTable(low.slice(0,6))}</section>`;}
function inventory(){const categories=[...new Set(state.products.map(p=>p.category))].sort();return heading(isStaff()?'YOUR WORKING CATALOGUE':'SMALL ELECTRONICS, CLEAR AVAILABILITY',isStaff()?'Inventory':'Find your next essential.',isStaff()?'Search, filter and open only the details you need.':'Browse prices and stock before visiting the store.',isStaff()?'<a class="button secondary" href="/api/endterm/export/stock">Export stock CSV</a>':'')+`<div class="filters"><label class="search">Search products<input id="inventorySearch" type="search" placeholder="Name or SKU…" value="${esc(state.query)}"></label><label>Category<select id="inventoryCategory"><option value="">All categories</option>${categories.map(c=>`<option ${state.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Availability<select id="inventoryStatus"><option value="">All stock</option>${[['healthy','In stock'],['low','Low stock'],['out','Out of stock']].map(([v,t])=>`<option value="${v}" ${state.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Sort by<select id="inventorySort">${[['sku','SKU'],['name','Name'],['quantity','Lowest stock'],['price','Lowest price']].map(([v,t])=>`<option value="${v}" ${state.sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div id="inventoryResults"></div><p class="toolbar-note">Photos are category illustrations, not verified images of each model. Open a product for its own videos.</p>`;}
function inventoryTable(rows){return `<div class="table-wrap responsive-table"><table><caption class="sr-only">Live product inventory</caption><thead><tr><th scope="col">Product</th><th scope="col">Category</th><th scope="col" class="numeric">Price</th><th scope="col" class="numeric">On hand</th><th scope="col">Status</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${productCell(p)}</td><td data-label="Category">${esc(p.category)}</td><td data-label="Price" class="numeric">${money(p.price)}</td><td data-label="On hand" class="numeric">${fmt(p.quantity)}</td><td data-label="Status">${badge(productStatus(p))}</td><td><button class="button small secondary" data-open="${p.product_id}" aria-label="Open ${esc(p.name)}">View →</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No products match these filters.</div></td></tr>'}</tbody></table></div>`;}
function inventoryResults(){if(!$('inventoryResults'))return;let rows=state.products.filter(p=>(!state.query||`${p.name} ${p.sku}`.toLowerCase().includes(state.query.toLowerCase()))&&(!state.category||p.category===state.category)&&(!state.status||productStatus(p)===state.status));rows.sort((a,b)=>['quantity','price'].includes(state.sort)?Number(a[state.sort])-Number(b[state.sort]):String(a[state.sort]).localeCompare(String(b[state.sort])));const pageSize=matchMedia('(max-width:740px)').matches?6:12;const total=rows.length,pages=Math.max(1,Math.ceil(total/pageSize));state.page=Math.min(pages,state.page);rows=rows.slice((state.page-1)*pageSize,state.page*pageSize);
 const body=isStaff()?inventoryTable(rows):`<div class="card-grid">${rows.map(p=>`<article class="product-card"><div class="photo"><img data-photo src="${picture(p)}" alt="" loading="lazy"><span class="photo-label">Category illustration</span></div><div class="body"><span class="sku">${esc(p.sku)}</span><h3>${esc(p.name)}</h3><div class="price">${money(p.price)}</div><div class="foot">${badge(productStatus(p))}<button class="button small secondary" data-open="${p.product_id}">Details →</button></div></div></article>`).join('')||'<div class="empty">No matching products.</div>'}</div>`;
 $('inventoryResults').innerHTML=`<div class="${isStaff()?'panel':''}">${body}<div class="table-footer"><span>${total} products · Page ${state.page} of ${pages}</span><div class="pagination"><button class="button small secondary" data-page="${state.page-1}" ${state.page===1?'disabled':''}>←</button><button class="button small secondary" data-page="${state.page+1}" ${state.page===pages?'disabled':''}>→</button></div></div></div>`;images();}
function analytics(){const d=state.analytics,s=d.summary;return heading('FROM NUMBERS TO DECISIONS','Know what moves.','Recorded sales, stock coverage and items worth reviewing.',range())+metaLine(d)+`<div class="filters compact"><label>Category<select id="analyticsCategory"><option value="">All categories</option>${d.categories.map(c=>`<option ${state.analyticsCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><div class="kpis">${kpi('Recorded units sold',fmt(s.units_sold),`${state.days} complete days`,'bag')}${kpi('Daily recorded rate',fmt(s.units_sold/state.days,2),'Units per calendar day','analytics')}${kpi('Coverage estimates',fmt(s.estimates_available),'Products with enough recorded evidence','clock')}${kpi('Stock without sales',money(s.no_recorded_sales_value),'At list price · review, not automatic discount','inventory',true)}</div><div class="grid-two">${trendPanel(d)}${barsPanel(d)}</div><div class="subhead"><h2>Sales leaders & stock coverage</h2><span class="tag">CURRENT STOCK / RECORDED RATE</span></div><section class="panel"><div class="table-wrap responsive-table"><table><caption class="sr-only">Top recorded sellers and indicative stock coverage</caption><thead><tr><th scope="col">Product</th><th scope="col" class="numeric">Units sold</th><th scope="col" class="numeric">Units / day</th><th scope="col">Cover estimate</th><th scope="col">Next action</th><th scope="col"></th></tr></thead><tbody>${d.fastest.map(p=>`<tr><td>${productCell(p)}</td><td data-label="Units sold" class="numeric">${fmt(p.sold_units)}</td><td data-label="Units / day" class="numeric">${fmt(p.recorded_units_per_day,2)}</td><td data-label="Cover estimate">${p.days_of_cover===null?'Not estimated':fmt(p.days_of_cover,1)+' days'}<span class="cell-note">${p.days_of_cover===null?'Limited sales evidence':'Constant-rate scenario'}</span></td><td data-label="Next action">${p.priority?esc(p.reason):'Monitor sales and availability'}</td><td><button class="button small secondary" data-open="${p.product_id}">Review →</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No sale movements in the selected period. Deliveries are not treated as sales.</div></td></tr>'}</tbody></table></div></section><div class="subhead"><h2>No recorded sales</h2><span class="tag">${state.days} DAYS · STOCK ON HAND</span></div><p class="muted small">Check availability history and product visibility before replenishing or discounting these items.</p><section class="panel spaced"><div class="table-wrap responsive-table"><table><caption class="sr-only">Review candidates with stock but no recorded sales</caption><thead><tr><th scope="col">Product</th><th scope="col" class="numeric">On hand</th><th scope="col" class="numeric">Stock at list price</th><th scope="col">Last recorded sale</th><th scope="col"></th></tr></thead><tbody>${d.no_sales.slice(0,8).map(p=>`<tr><td>${productCell(p)}</td><td data-label="On hand" class="numeric">${fmt(p.quantity)}</td><td data-label="At list price" class="numeric">${money(p.listed_stock_value)}</td><td data-label="Last recorded sale">${dateLabel(p.last_sale_at)}</td><td><button class="button small secondary" data-open="${p.product_id}">Review →</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Every stocked product has at least one recorded sale in this window.</div></td></tr>'}</tbody></table></div></section>${methods(d)}`;}
function restock(){const d=state.analytics;return heading('A SHORTLIST, NOT AN AUTOMATIC ORDER','Replenishment','Prioritise stock risks, then confirm supplier details.',`<a class="button" href="/api/studio/reorder.csv?${params()}">Export review CSV ${icon('arrow')}</a>`)+metaLine(d)+`<section class="panel settings-panel"><h3>Planning assumptions</h3><p class="muted small">Adjust the scenario. These values are not supplier commitments or purchase orders.</p><form id="planningForm" class="filters"><label>Sales window<select id="planDays">${[7,30,90].map(n=>`<option value="${n}" ${n===state.days?'selected':''}>${n} complete days</option>`).join('')}</select></label><label>Lead time · days<input id="planLead" type="number" min="0" max="90" required value="${state.lead}"></label><label>Review cycle · days<input id="planReview" type="number" min="1" max="90" required value="${state.review}"></label><label>Buffer · days<input id="planBuffer" type="number" min="0" max="30" required value="${state.buffer}"></label><button class="button" type="submit">Recalculate</button></form></section><div class="subhead"><h2>${d.queue.length} products to review</h2><span class="tag">NO STOCK CHANGES</span></div><section class="panel">${queueTable(d.queue)}</section><div class="insight-inline">Check open orders, supplier pack sizes and recent stockouts before ordering. A recorded delivery should only be entered when goods actually arrive.</div>${methods(d)}`;}
function activity(){return heading('EVERY CHANGE HAS A RECORD','Stock activity','A readable movement history, separate from the catalogue.','<a class="button secondary" href="/api/endterm/export/movements">Export movements CSV</a>')+`<div class="filters"><label>Operation<select id="historyReason"><option value="">All operations</option>${['sale','delivery','correction'].map(r=>`<option value="${r}" ${state.historyReason===r?'selected':''}>${r[0].toUpperCase()+r.slice(1)}</option>`).join('')}</select></label></div><section class="panel"><div class="table-wrap responsive-table"><table><caption class="sr-only">Latest 100 inventory movements</caption><thead><tr><th scope="col">Product</th><th scope="col">Operation</th><th scope="col" class="numeric">Change</th><th scope="col">Recorded</th><th scope="col">Reference</th><th scope="col"></th></tr></thead><tbody>${state.movements.map(m=>`<tr><td><strong>${esc(m.name)}</strong><span class="sku">${esc(m.sku)}</span></td><td data-label="Operation"><span class="badge ${m.reason==='delivery'?'published':m.reason==='sale'?'neutral':'watch'}">${esc(m.reason)}</span></td><td data-label="Change" class="numeric">${m.quantity_change>0?'+':''}${fmt(m.quantity_change)}</td><td data-label="Recorded">${stamp(m.created_at)}</td><td data-label="Reference">#${m.movement_id}<span class="cell-note">Staff ID ${m.user_id}</span></td><td><button class="button small secondary" data-open="${m.product_id}" data-tab="history">View →</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No movements match this filter.</div></td></tr>'}</tbody></table></div><div class="table-footer">Latest 100 records · full history is available in the CSV export</div></section>`;}
function media(){const rows=state.videos.filter(v=>!state.mediaStatus||v.status===state.mediaStatus);return heading('PRODUCT MEDIA','Show, then publish.',isStaff()?'Review product demonstrations without cluttering the inventory screen.':'Published product demonstrations from the store.',isStaff()?'<a href="#inventory" class="button secondary">Choose product to upload →</a>':'')+(isStaff()?`<div class="filters"><label>Publication status<select id="mediaStatus"><option value="">All available videos</option>${['pending','published','rejected','archived','uploading'].map(s=>`<option value="${s}" ${state.mediaStatus===s?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></label></div>`:'')+`<div class="card-grid media">${rows.map(v=>`<article class="panel media-card"><div class="media-cover">${icon('media')}</div>${badge(v.status)}<h3>${esc(v.title)}</h3><p>${esc(v.sku)} · ${esc(v.product_name)}</p><div class="foot"><span class="muted small">${v.duration_seconds?fmt(v.duration_seconds,1)+' sec':'Upload not complete'}</span><button class="button small secondary" data-open="${v.product_id}" data-tab="videos">${v.status==='published'?'Watch':'Review'} →</button></div></article>`).join('')||`<section class="panel empty"><h3>No videos here yet.</h3><p>${isStaff()?'Open a product to upload a demonstration. The administrator controls publication.':'Only published clips appear here.'}</p></section>`}</div><p class="toolbar-note">${isStaff()?'Latest 100 accessible videos. Upload and publication errors appear next to the action.':'A product demonstration is not a guarantee for every item in stock.'}</p>`;}
function settings(){return heading('LESS CLUTTER, MORE CONTEXT','Help & settings','Advanced details stay here, not in every product card.')+`<div class="help-grid"><section class="panel panel-body"><h3>Refresh behaviour</h3><p class="muted small">Use the refresh button any time. Automatic refresh pauses while a dialog is open.</p><label class="check"><input id="autoRefresh" type="checkbox" ${state.auto?'checked':''}> Refresh catalogue every 10 seconds</label><p class="fine-print">Turn this off during a controlled Network measurement.</p></section><section class="panel panel-body"><h3>Your access</h3><p class="muted small">${roleName(state.user?.role)}</p><div class="insight-inline">${isAdmin()?'You can manage stock, edit products, publish videos and read live analytics.':isStaff()?'You can record sales and deliveries, export stock and submit your own videos.':'You can browse products and watch published videos. Inventory changes are restricted.'}</div><p class="fine-print">Permissions are checked by the server on each protected request.</p></section><section class="panel panel-body"><h3>Photographs & video</h3><p class="muted small">Current photographs illustrate categories. They are not exact-model product images.</p><p class="fine-print">Upload only your own authorised recordings. Product videos are stored separately from PostgreSQL metadata.</p></section><section class="panel panel-body"><h3>Integrated tools</h3><p class="muted small">Barcode simulator is part of the workspace. Historical A3 charts are inside Analytics for administrators.</p><div class="action-row"></div></section></div>`;}
async function render(fetchData=true){const seq=++state.sequence;state.route=location.hash.slice(1)|| (isStaff()?'overview':'inventory');if(!allowed(state.route))state.route='inventory';nav();closeMenu();$('page').innerHTML='<div class="eyebrow">YOUR STORE</div><div class="skeleton" aria-label="Loading" role="status"></div>';
 try{
  if(isAdmin()&&['overview','analytics','restock'].includes(state.route)&&!(state.route==='analytics'&&Final.isHistorical())&&(!state.analytics||fetchData))state.analytics=await api('/api/studio/analytics?'+params());
  if(state.route==='analytics'&&isAdmin()&&Final.isHistorical())await Final.loadHistorical(api,fetchData);
  if(state.route==='barcode'&&isStaff())await Final.loadBarcode(api);
  if(state.route==='activity')state.movements=(await api('/api/studio/movements?'+new URLSearchParams({reason:state.historyReason}))).rows;
  if(state.route==='media')state.videos=(await api('/api/studio/videos')).rows;
  if(seq!==state.sequence)return;
  $('page').innerHTML=state.route==='analytics'?(Final.isHistorical()?Final.historicalHtml():Final.tabTitle()+analytics()):({overview,inventory,analytics,restock,activity,media,settings,barcode:()=>Final.barcodeHtml()}[state.route]||inventory)();
  if(state.route==='inventory')inventoryResults();images();widths();nav();
 }catch(e){if(seq!==state.sequence)return;$('page').innerHTML=`<section class="panel empty"><h3>This view is unavailable.</h3><p>${esc(e.message)}</p><p class="fine-print">No example values have been substituted for your database.</p><button class="button" data-reload>Try again</button></section>`;}
}
async function refresh(){const products=await api('/api/products');state.products=products;state.analytics=null;$('sync').textContent='Synced '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});$('connectionLabel').textContent=PREVIEW?'Simulated preview':'Store connection active';await render(true);}
function openLogin(){$('loginError').textContent='';$('loginDialog').showModal();$('email').focus();}
function product(){return state.products.find(p=>Number(p.product_id)===Number(state.productId));}
async function openProduct(id,tab='details'){
 state.productId=Number(id);state.tab=tab;const p=product();if(!p)return notice('This product is no longer in the loaded catalogue. Refresh and try again.',true);
 $('productBody').innerHTML=`<div class="drawer-head"><button class="icon-button dialog-close" data-close="productDialog" aria-label="Close product details">×</button><div class="eyebrow">${esc(p.sku)} · ${esc(p.category)}</div><h2 id="productTitle">${esc(p.name)}</h2></div><div class="drawer-tabs" role="tablist" aria-label="Product sections">${[['details','Details'],['videos','Videos'],...(isStaff()?[['history','History']]:[])].map(([k,t])=>`<button id="tab-${k}" role="tab" aria-selected="${state.tab===k}" aria-controls="drawerPanel" tabindex="${state.tab===k?0:-1}" data-product-tab="${k}">${t}</button>`).join('')}</div><div class="drawer-content" id="drawerPanel" role="tabpanel" tabindex="0" aria-labelledby="tab-${state.tab}"></div>`;
 if(!$('productDialog').open)$('productDialog').showModal();
 const pane=$('drawerPanel');
 if(tab==='details'){
 pane.innerHTML=`<div class="detail-top"><div><img data-photo src="${picture(p)}" alt="Category illustration, not an exact model photograph"><span class="sku">Category illustration</span></div><div>${badge(productStatus(p))}<div class="price">${money(p.price)}</div><span class="muted small">${esc(p.category)}</span></div></div><div class="detail-numbers"><div class="detail-number"><small>AVAILABLE UNITS</small><strong>${fmt(p.quantity)}</strong></div><div class="detail-number"><small>${isStaff()?'REORDER THRESHOLD':'PUBLISHED VIDEOS'}</small><strong>${isStaff()?fmt(p.reorder_threshold):fmt(p.video_count)}</strong></div></div>${isStaff()?`<button class="button full" data-record="${p.product_id}">${icon('plus')} Record stock change</button>`:''}${isAdmin()?`<details><summary>Edit product details</summary><form id="editProductForm"><label>Product name<input id="editName" required minlength="2" maxlength="150" value="${esc(p.name)}"></label><div class="form-row"><label>Price · KZT<input id="editPrice" type="number" min="0" max="10000000" step="0.01" value="${Number(p.price)}" required></label><label>Reorder threshold<input id="editThreshold" type="number" min="0" max="10000" step="1" value="${Number(p.reorder_threshold)}" required></label></div><p class="inline-message" id="editError" role="alert"></p><button class="button" type="submit">Save details</button></form></details>`:''}<details><summary>About this image and recording</summary><p class="fine-print">This photo represents a product category. Check the model name and specifications. Video demonstrations are additional information, not independent certification of every unit.</p></details>`;images();
 }else if(tab==='history'){
 pane.textContent='Loading movement history…';try{const rows=await api(`/api/products/${id}/movements`);if(state.productId!==Number(id)||state.tab!==tab)return;pane.innerHTML=`<p class="muted small">Latest 20 movements for ${esc(p.sku)}.</p>${rows.map(m=>`<div class="history-entry"><div><strong>${esc(m.reason)} · #${m.movement_id}</strong><small>${stamp(m.created_at)}</small></div><strong class="${m.quantity_change>0?'positive':'negative'}">${m.quantity_change>0?'+':''}${fmt(m.quantity_change)}</strong></div>`).join('')||'<div class="empty">No movement history for this product.</div>'}`;}catch(e){pane.textContent=e.message;}
 }else{
 pane.innerHTML='<p class="muted small">Loading product videos…</p>';await loadProductVideos(id);
 }
}
async function loadProductVideos(id){
 const pane=$('drawerPanel');try{
 const rows=await api(`/api/products/${id}/videos`);if(state.productId!==Number(id)||state.tab!=='videos')return;
 pane.innerHTML=`<p class="fine-print">A store demonstration is not an independent inspection. Only published videos are visible to buyers.</p><div id="mediaFeedback" role="status" class="inline-message"></div><div id="videoEntries">${rows.map(v=>`<article class="video-entry">${badge(v.status)}<h3>${esc(v.title)}</h3><p class="fine-print">${v.duration_seconds?fmt(v.duration_seconds,1)+' seconds · ':''}${v.scope==='specific_unit'?'Unit: '+esc(v.unit_reference):'Model example'}</p>${v.status!=='uploading'?`<video controls playsinline preload="none" src="${esc(v.file_url)}" aria-label="${esc(v.title)}"></video><details><summary>Transcript / description</summary><p class="fine-print">${esc(v.transcript)}</p></details>`:''}<div class="actions">${v.status!=='uploading'?`<a class="button small secondary" href="${esc(v.download_url)}">Download MP4</a>`:''}${isAdmin()&&['pending','rejected','archived'].includes(v.status)?`<button class="button small" data-video-status="published" data-video-id="${esc(v.video_id)}">Publish</button>`:''}${isAdmin()&&v.status==='pending'?`<button class="button small secondary" data-video-status="rejected" data-video-id="${esc(v.video_id)}">Reject</button>`:''}${isAdmin()&&v.status==='published'?`<button class="button small secondary" data-video-status="archived" data-video-id="${esc(v.video_id)}">Unpublish</button>`:''}</div></article>`).join('')||'<div class="empty"><h3>No published video yet.</h3><p>There is no completed product demonstration to show.</p></div>'}</div>${isStaff()?`<details><summary>Upload a product video</summary><p class="fine-print">MP4 · H.264 · AAC or no audio · up to 60 seconds / 40 MiB / 1080p.</p><form id="uploadVideoForm"><label>Video file<input id="videoFile" type="file" accept="video/mp4,.mp4" required></label><label>Title<input id="videoTitle" minlength="3" maxlength="120" required></label><label>Recording shows<select id="videoScope"><option value="model_example">An example of this model</option><option value="specific_unit">A specific unit / batch</option></select></label><label id="unitLabel" hidden>Unit / batch reference<input id="unitRef" minlength="2" maxlength="100"></label><label>Recorded on · optional<input id="videoDate" type="date"></label><label>Transcript / description<textarea id="videoTranscript" minlength="10" maxlength="5000" required></textarea></label><label class="check"><input id="videoOwned" type="checkbox" required> Our team owns this recording and has permission from anyone shown.</label><p class="inline-message" id="uploadError" role="status"></p><button id="uploadSubmit" class="button" type="submit">Upload for review</button></form></details>`:''}`;
 }catch(e){pane.innerHTML=`<p class="inline-message" role="alert">${esc(e.message)}</p>`;}
}
function openStock(id){const p=state.products.find(x=>Number(x.product_id)===Number(id));if(!p||!isStaff())return;$('stockId').value=p.product_id;$('stockProduct').textContent=p.sku+' · '+p.name;$('stockReason').innerHTML='<option value="sale">Sale</option><option value="delivery">Delivery</option>'+(isAdmin()?'<option value="correction">Correction</option>':'');$('stockQty').value=1;$('stockError').textContent='';$('stockDialog').showModal();previewStock();}
function previewStock(){const p=state.products.find(x=>Number(x.product_id)===Number($('stockId').value));if(!p)return;const correction=$('stockReason').value==='correction';$('stockQty').min=correction?-10000:1;const n=Number($('stockQty').value),change=$('stockReason').value==='sale'?-n:n;const next=Number(p.quantity)+change;$('stockPreview').innerHTML=`On hand <strong>${fmt(p.quantity)}</strong> <span aria-hidden="true">→</span> After confirmation <strong>${fmt(next)}</strong>${next<0?'<p>This operation exceeds available stock.</p>':''}${correction?'<p class="small">Correction: enter a signed change, not the new total.</p>':''}`;}
async function stockSubmit(e){e.preventDefault();const button=$('stockSubmit');if(button.disabled)return;button.disabled=true;$('stockError').textContent='';const id=Number($('stockId').value);const reason=$('stockReason').value,n=Number($('stockQty').value),quantity_change=reason==='sale'?-n:n;
 try{const r=await api('/api/stock-movements',{method:'POST',body:JSON.stringify({product_id:id,quantity_change,reason})});if(r.new_alert&&$('stockSound').checked)new Audio('/media/alert.wav').play().catch(()=>{});$('stockDialog').close();await refresh();if($('productDialog').open)await openProduct(id,'details');notice(`${r.sku}: saved. ${r.quantity} units in stock.${r.new_alert?' A new low-stock alert was created.':''}`);}catch(err){$('stockError').textContent=err.message+(err.status?'':' Check product history before retrying.');}finally{button.disabled=false;}}
async function editSubmit(e){e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;try{await api(`/api/products/${state.productId}`,{method:'PATCH',body:JSON.stringify({name:$('editName').value,price:Number($('editPrice').value),reorder_threshold:Number($('editThreshold').value)})});const id=state.productId;await refresh();await openProduct(id,'details');notice('Product details saved.');}catch(err){$('editError').textContent=err.message;}finally{b.disabled=false;}}
async function uploadSubmit(e){e.preventDefault();const file=$('videoFile').files[0];if(!file||!file.name.toLowerCase().endsWith('.mp4'))return $('uploadError').textContent='Select an MP4 file.';if(file.size>(state.config.max_video_bytes||41943040))return $('uploadError').textContent='The file exceeds the 40 MiB limit.';const b=$('uploadSubmit');b.disabled=true;const id=state.productId;let reservation=null;
 try{$('uploadError').textContent='Uploading and validating. Keep this dialog open…';reservation=await api(`/api/products/${id}/videos`,{method:'POST',body:JSON.stringify({title:$('videoTitle').value,transcript:$('videoTranscript').value,scope:$('videoScope').value,unit_reference:$('unitRef').value,recorded_on:$('videoDate').value||null,own_content:$('videoOwned').checked})});await api(`/api/videos/${reservation.video_id}/content`,{method:'PUT',headers:{'Content-Type':'video/mp4'},body:file,timeout:180000});reservation=null;await loadProductVideos(id);if($('mediaFeedback')){$('mediaFeedback').textContent='Upload saved for review. An administrator must publish it.';$('mediaFeedback').className='inline-message success';}}catch(err){if(reservation)await api(`/api/videos/${reservation.video_id}/upload`,{method:'DELETE'}).catch(()=>{});if($('uploadError'))$('uploadError').textContent=err.message;}finally{b.disabled=false;}}
async function videoStatus(button){const id=button.dataset.videoId,status=button.dataset.videoStatus;button.disabled=true;const msg=$('mediaFeedback');msg.textContent='Saving publication status…';
 try{await api(`/api/videos/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});await loadProductVideos(state.productId);if($('mediaFeedback')){$('mediaFeedback').textContent=`Video ${status}.`;$('mediaFeedback').className='inline-message success';}state.products=await api('/api/products');if(state.route==='media')await render();}catch(e){msg.textContent=`Could not change status: ${e.message}`;msg.scrollIntoView({block:'nearest'});}finally{button.disabled=false;}}
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();const b=$('loginSubmit');b.disabled=true;try{state.user=await api('/api/login',{method:'POST',body:JSON.stringify({email:$('email').value,password:$('password').value})});$('password').value='';$('loginDialog').close();state.analytics=null;Final.clearSession();location.hash=isStaff()?'overview':'inventory';await refresh();}catch(err){state.user=null;$('loginError').textContent=err.message;nav();}finally{b.disabled=false;}});
$('signInButton').onclick=openLogin;$('accountButton').onclick=()=>state.user?(location.hash='settings'):openLogin();
$('logoutButton').onclick=async()=>{try{await api('/api/logout',{method:'POST'});state.user=null;state.analytics=null;Final.clearSession();location.hash='inventory';await refresh();}catch(e){notice(e.message,true);}};
$('refreshButton').onclick=()=>refresh().catch(e=>notice(e.message,true));$('stockForm').onsubmit=stockSubmit;
$('stockReason').onchange=previewStock;$('stockQty').oninput=previewStock;
$('menuButton').onclick=()=>{const open=!$('sidebar').classList.contains('open');$('sidebar').classList.toggle('open',open);$('shade').hidden=!open;$('menuButton').setAttribute('aria-expanded',String(open));};$('shade').onclick=closeMenu;
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.route==='inventory')inventoryResults();},220);});
window.addEventListener('hashchange',()=>{notice('');render();});
document.addEventListener('click',async e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.close){$(b.dataset.close).close();return;}
 if(b.dataset.email){$('email').value=b.dataset.email;$('password').value=state.config.demo_password||'';return;}
 if(b.dataset.open){openProduct(b.dataset.open,b.dataset.tab||'details');return;}
 if(b.dataset.record){openStock(b.dataset.record);return;}
 if(b.dataset.productTab){openProduct(state.productId,b.dataset.productTab);return;}
 if(b.dataset.videoStatus){await videoStatus(b);return;}
 if(b.dataset.finalMode){Final.setMode(b.dataset.finalMode);await render(true);return;}
 if(b.dataset.finalAction){await Final.doAction(b.dataset.finalAction,api,()=>render(false));return;}
 if(b.hasAttribute('data-clear-scope')){state.analyticsCategory='';state.analytics=null;await render();return;}
 if(b.dataset.days){state.days=Number(b.dataset.days);state.analytics=null;await render();return;}
 if(b.dataset.page){state.page=Number(b.dataset.page);inventoryResults();return;}
 if(b.hasAttribute('data-reload'))refresh().catch(err=>notice(err.message,true));
 if(PREVIEW&&b.tagName==='A'&&b.getAttribute('href')?.startsWith('/')){e.preventDefault();notice('This link connects to your real app after installation. The preview does not export or modify live records.');}
});
document.addEventListener('input',e=>{if(e.target.id==='inventorySearch'){state.query=e.target.value;state.page=1;inventoryResults();}if(e.target.id==='finalBarcodeUnits')Final.updatePreview();});
document.addEventListener('change',e=>{
 const mapping={inventoryCategory:'category',inventoryStatus:'status',inventorySort:'sort'};
 if(mapping[e.target.id]){state[mapping[e.target.id]]=e.target.value;state.page=1;inventoryResults();}
 if(e.target.id==='analyticsCategory'){state.analyticsCategory=e.target.value;state.analytics=null;render();}
 if(e.target.id==='historyReason'){state.historyReason=e.target.value;render();}
 if(e.target.id==='mediaStatus'){state.mediaStatus=e.target.value;render(false);}
 if(e.target.id==='autoRefresh')state.auto=e.target.checked;
 if(e.target.id==='videoScope'){$('unitLabel').hidden=e.target.value!=='specific_unit';$('unitRef').required=e.target.value==='specific_unit';}
 if(e.target.id==='finalBarcodeReason')Final.updatePreview();
});
document.addEventListener('submit',e=>{if(e.target.id==='finalBarcodeScanForm'){e.preventDefault();Final.submitScan(e.target,api,()=>render(false));return;}if(e.target.id==='finalBarcodeConfirmForm'){e.preventDefault();Final.submitConfirm(e.target,api,()=>render(false));return;}if(e.target.id==='editProductForm')editSubmit(e);if(e.target.id==='uploadVideoForm')uploadSubmit(e);if(e.target.id==='planningForm'){e.preventDefault();state.days=Number($('planDays').value);state.lead=Number($('planLead').value);state.review=Number($('planReview').value);state.buffer=Number($('planBuffer').value);state.analytics=null;render();}});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape')closeMenu();
 if(e.target.matches('[data-product-tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-product-tab]')],i=tabs.indexOf(e.target);const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;const id=tabs[n].dataset.productTab;openProduct(state.productId,id).then(()=>document.querySelector(`[data-product-tab="${id}"]`)?.focus());}
});
$('productDialog').addEventListener('close',()=>{$('productBody').querySelectorAll('video').forEach(v=>v.pause());});
setInterval(async()=>{if(!state.auto||document.hidden||document.querySelector('dialog[open]')||!['inventory','overview'].includes(state.route)||document.activeElement?.tagName==='INPUT')return;try{state.products=await api('/api/products');$('sync').textContent='Synced '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});if(state.route==='inventory')inventoryResults();else await render();}catch(e){notice('Refresh unavailable. Displayed data may be out of date.',true);}},10000);
async function init(){
 if(PREVIEW){$('previewBanner').hidden=false;state.days=30;}
 try{state.config=await api('/api/config');if(state.config.demo){$('demoAccounts').hidden=false;$('demoContent').innerHTML=state.config.demo_accounts.map(a=>`<button type="button" data-email="${esc(a.email)}">${esc(a.role)}</button>`).join('')+`<p>Shared demo password: <code>${esc(state.config.demo_password)}</code></p><p>Coursework only. Do not use these accounts for real customer data.</p>`;}
 try{state.user=await api('/api/me');}catch(e){if(e.status!==401)throw e;state.user=null;}
 state.view=isStaff()?'table':'grid';await refresh();
 }catch(e){notice(e.message+' Start PostgreSQL and the existing Express server.',true);$('page').innerHTML='<section class="panel empty"><h3>Your store is not connected.</h3><p>No placeholder analytics will be shown as live records.</p></section>';nav();}
}
init();
})();
